@using Tempo.Blazor.Components.Inputs
@using Tempo.Blazor.Models

<TmSelect TValue="string"
          @bind-Value="_selectedCountry"
          Label="Country"
          Placeholder="Choose a country"
          Options="@_countryOptions" />

<p>Selected: @_selectedCountry</p>

@code {
    private string? _selectedCountry;

    private List<SelectOption<string>> _countryOptions =
    [
        new("CZ", "Czech Republic"),
        new("SK", "Slovakia"),
        new("DE", "Germany"),
        new("AT", "Austria")
    ];
}

@* Set Value or the bound variable to pre-select an option.
   The value must match one of the SelectOption.Value values. *@

<TmSelect TValue="string"
          @bind-Value="_selectedRole"
          Label="Role"
          Options="@_roleOptions" />

@code {
    // Pre-selected to "editor" on load
    private string? _selectedRole = "editor";

    private List<SelectOption<string>> _roleOptions =
    [
        new("admin", "Administrator"),
        new("editor", "Editor"),
        new("viewer", "Viewer")
    ];
}

@* Numeric TValue (short, ushort, long, ulong, uint, byte, sbyte, decimal, double, float —
   and their nullable forms) round-trips through the Options parameter regardless of the ambient
   thread culture: the option value and the parsed-back value both use CultureInfo.InvariantCulture,
   so a decimal like 1.5 always renders and parses as "1.5", never a culture-specific "1,5".
   TValue is decimal? here (not decimal) so "no selection" (null) stays distinguishable from the
   0m option below — a non-nullable decimal can't tell "nothing picked" apart from an actual 0m. *@

<TmSelect TValue="decimal?"
          @bind-Value="_selectedDiscount"
          Label="Discount rate"
          Placeholder="Select discount"
          Options="@_discountOptions" />

<p>Selected: @_selectedDiscount</p>

@code {
    private decimal? _selectedDiscount;

    private List<SelectOption<decimal?>> _discountOptions =
    [
        new(0m, "None"),
        new(1.5m, "1.5 %"),
        new(2.75m, "2.75 %")
    ];
}

@* A null-valued SelectOption is a real, pickable <option value="">: with the bound
   value at null it renders marked selected, the <select> carries value="" so the
   preselection lands on it (never on the first option by accident), and picking it fires
   ValueChanged(null). Works the same for int?, Guid?, enum? and string. *@

<TmSelect TValue="decimal?"
          @bind-Value="_parentCategoryId"
          Label="Parent category"
          Options="@_categoryTreeOptions" />

<p>Parent: @(_parentCategoryId?.ToString() ?? "null (root)")</p>

@code {
    private decimal? _parentCategoryId; // null on purpose — the root option is selected on load

    private List<SelectOption<decimal?>> _categoryTreeOptions =
    [
        new(null, "Root (no parent)"),
        new(1m, "Electronics"),
        new(2m, "Books")
    ];
}

@* PlaceholderSelectable turns the placeholder into a real option: the user can pick it to
   clear the selection back to default(TValue) (null for nullable types). Default is false,
   which keeps the placeholder disabled and purely decorative. *@

<TmSelect TValue="int?"
          @bind-Value="_priority"
          Label="Priority"
          Placeholder="No priority"
          PlaceholderSelectable="true"
          Options="@_priorityOptions" />

@code {
    private int? _priority = 2;

    private List<SelectOption<int?>> _priorityOptions =
    [
        new(1, "Low"),
        new(2, "Medium"),
        new(3, "High")
    ];
}

@* Error takes priority over HelpText — when Error is set, HelpText is hidden. *@

<TmSelect TValue="string"
          @bind-Value="_selectedDepartment"
          Label="Department"
          Placeholder="Select department"
          Error="@_error"
          HelpText="Choose your primary department"
          Options="@_departments" />

<button @onclick="Validate">Submit</button>

@code {
    private string? _selectedDepartment;
    private string? _error;

    private List<SelectOption<string>> _departments =
    [
        new("IT", "IT"),
        new("HR", "Human Resources"),
        new("FIN", "Finance")
    ];

    private void Validate()
    {
        _error = string.IsNullOrEmpty(_selectedDepartment)
            ? "Please select a department"
            : null;
    }
}

@* Use ChildContent when you need full control over <option> elements
   instead of using the Options parameter. The bound Value is preselected on
   load — no need to add a `selected` attribute to the <option> yourself. *@

<TmSelect TValue="string"
          @bind-Value="_selectedPriority"
          Label="Priority">
    <option value="" disabled>-- Select priority --</option>
    <option value="low">🟢 Low</option>
    <option value="medium">🟡 Medium</option>
    <option value="high">🔴 High</option>
    <option value="critical" disabled>⛔ Critical (admin only)</option>
</TmSelect>

@code {
    // Loaded as "high" — the dropdown opens on High, not the first option.
    private string? _selectedPriority = "high";
}

@using Tempo.Blazor.Components.Inputs
@using Tempo.Blazor.Models
@inject HttpClient Http

<TmSelect TValue="int"
          @bind-Value="_selectedProjectId"
          Label="Project"
          Placeholder="Select project"
          Disabled="@_isLoading"
          Options="@_projectOptions" />

@code {
    private int _selectedProjectId;
    private List<SelectOption<int>> _projectOptions = [];
    private bool _isLoading = true;

    protected override async Task OnInitializedAsync()
    {
        var projects = await Http.GetFromJsonAsync<List<ProjectDto>>("/api/projects");
        _projectOptions = projects?.Select(p => new SelectOption<int>(p.Id, p.Name)).ToList() ?? [];
        _isLoading = false;
    }
}

@* Second select depends on the first. When country changes,
   city options are reloaded. *@

<TmSelect TValue="string"
          Value="@_selectedCountry"
          ValueChanged="OnCountryChanged"
          Label="Country"
          Placeholder="Select country"
          Options="@_countries" />

<TmSelect TValue="string"
          @bind-Value="_selectedCity"
          Label="City"
          Placeholder="Select city"
          Disabled="@(string.IsNullOrEmpty(_selectedCountry))"
          Options="@_cities" />

@code {
    private string? _selectedCountry;
    private string? _selectedCity;
    private List<SelectOption<string>> _countries =
    [
        new("CZ", "Czech Republic"),
        new("SK", "Slovakia")
    ];
    private List<SelectOption<string>> _cities = [];

    private async Task OnCountryChanged(string? country)
    {
        _selectedCountry = country;
        _selectedCity = null; // Reset city when country changes

        _cities = country switch
        {
            "CZ" => [new("PRG", "Prague"), new("BRN", "Brno")],
            "SK" => [new("BA", "Bratislava"), new("KE", "Košice")],
            _ => []
        };
    }
}
